bool stratum_subscribe(struct pool *pool) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;
    long http_code = 0;
    char *response = NULL;
    bool success = false;

    curl = curl_easy_init();
    if (!curl)
        return false;

    headers = curl_slist_append(headers, "Content-Type: application/json");
    curl_easy_setopt(curl, CURLOPT_URL, pool->url);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);

    char json_req[1024];
    snprintf(json_req, sizeof(json_req),
             "{"
             "  \"jsonrpc\": \"2.0\","
             "  \"method\": \"mining.subscribe\","
             "  \"params\": [\"stratum-client\"],"
             "  \"id\": 1"
             "}");

    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_req);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        applog(LOG_ERR, "Failed to subscribe to Stratum: %s", curl_easy_strerror(res));
        goto cleanup;
    }

    res = curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    if (res != CURLE_OK || http_code != 200) {
        applog(LOG_ERR, "Unexpected HTTP response code: %ld", http_code);
        goto cleanup;
    }

    cJSON *root = cJSON_Parse(response);
    if (!root) {
        applog(LOG_ERR, "Failed to parse Stratum subscription response.");
        goto cleanup;
    }

    cJSON *result = cJSON_GetObjectItemCaseSensitive(root, "result");
    if (!result || !cJSON_IsArray || cJSON_GetArraySize(result) < 2) {
        applog(LOG_ERR, "Invalid subscription result format.");
        goto cleanup;
    }

    char *session_id = cJSON_GetArrayItemCaseSensitive(result, 1)->valuestring;
    char *nonce = cJSON_GetArrayItemCaseSensitive(result, 2)->valuestring;

    if (!session_id || !nonce) {
        applog(LOG_ERR, "Failed to extract session ID or nonce from response.");
        goto cleanup;
    }

    strncpy(pool->session_id, session_id, sizeof(pool->session_id) - 1);
    strncpy(pool->nonce, nonce, sizeof(pool->nonce) - 1);

    success = true;
    applog(LOG_INFO, "Stratum session established with session ID: %s", pool->session_id);

cleanup:
    if (curl)
        curl_easy_cleanup(curl);
    if (headers)
        curl_slist_free_all(headers);
    if (response)
        free(response);
    if (root)
        cJSON_Delete(root);

    return success;
}

bool initiate_stratum_session(struct pool *pool) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;
    long http_code;
    char *response = NULL;
    size_t response_len = 0;
    json_t *json_response;
    json_error_t error;
    const char *session_id = NULL;
    const char *nonce = NULL;

    curl = curl_easy_init();
    if (!curl) {
        applog(LOG_ERR, "Failed to initialize CURL for Stratum session");
        return false;
    }

    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        applog(LOG_ERR, "Failed to set CURL headers for Stratum session");
        curl_easy_cleanup(curl);
        return false;
    }

    curl_easy_setopt(curl, CURLOPT_URL, pool->stratum_url);
    curl_easy_setopt(curl, CURLOPT_POST, 1);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, "{\"jsonrpc\": \"2.0\", \"method\": \"mining.subscribe\", \"params\": [\"client/0.1\"], \"id\": 1}");
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);
    curl_easy_setopt(curl, CURLOPT_HEADER, 0);
    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);

    res = curl_easy_perform(curl);
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);

    if (res != CURLE_OK || http_code != 200) {
        applog(LOG_ERR, "Failed to connect to Stratum pool: %s", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
        free(response);
        return false;
    }

    json_response = json_loads(response, 0, &error);
    if (!json_response) {
        applog(LOG_ERR, "Failed to parse Stratum response: %s", error.text);
        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
        free(response);
        return false;
    }

    json_t *result = json_object_get(json_response, "result");
    if (!result || !json_is_array(result) || json_array_size(result) < 2) {
        applog(LOG_ERR, "Stratum response does not contain valid result array");
        json_decref(json_response);
        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
        free(response);
        return false;
    }

    session_id = json_string_value(json_array_get(result, 0));
    nonce = json_string_value(json_array_get(result, 1));

    if (!session_id || !nonce) {
        applog(LOG_ERR, "Failed to extract session ID or nonce from Stratum response");
        json_decref(json_response);
        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
        free(response);
        return false;
    }

    strncpy(pool->session_id, session_id, sizeof(pool->session_id) - 1);
    strncpy(pool->nonce, nonce, sizeof(pool->nonce) - 1);

    applog(LOG_INFO, "Stratum session initiated. Session ID: %s, Nonce: %s", session_id, nonce);

    json_decref(json_response);
    curl_easy_cleanup(curl);
    curl_slist_free_all(headers);
    free(response);

    return true;
}

bool stratum_subscribe(struct pool *pool) {
    CURL *curl;
    CURLcode res;
    struct curl_simplesocket *sock;
    struct jsonrpc_request *req;
    struct jsonrpc_response *resp;
    char *json_str;
    json_t *result;

    if (!pool || !pool->url) {
        return false;
    }

    curl = curl_easy_init();
    if (!curl) {
        applog(LOG_ERR, "Failed to initialize CURL session for pool: %s", pool->url);
        return false;
    }

    /* Set up the connection for the Stratum protocol */
    curl_easy_setopt(curl, CURLOPT_URL, pool->url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, jsonrpc_response_write);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &resp);
    curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1);

    req = jsonrpc_request_new("mining.subscribe", NULL, NULL);
    if (!req) {
        curl_easy_cleanup(curl);
        return false;
    }

    json_str = jsonrpc_request_serialize(req);
    if (!json_str) {
        jsonrpc_request_free(req);
        curl_easy_cleanup(curl);
        return false;
    }

    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_str);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        applog(LOG_ERR, "CURL request failed for pool: %s (%s)", pool->url, curl_easy_strerror(res));
        jsonrpc_request_free(req);
        curl_easy_cleanup(curl);
        return false;
    }

    if (!resp || resp->error) {
        applog(LOG_ERR, "Received error from pool: %s", resp->error);
        jsonrpc_request_free(req);
        curl_easy_cleanup(curl);
        return false;
    }

    result = resp->result;
    if (!result) {
        applog(LOG_ERR, "Invalid response from pool: missing result field");
        jsonrpc_request_free(req);
        curl_easy_cleanup(curl);
        return false;
    }

    if (!json_is_array(result)) {
        applog(LOG_ERR, "Result is not a JSON array");
        jsonrpc_request_free(req);
        curl_easy_cleanup(curl);
        return false;
    }

    json_t *session_id = json_array_get(result, 0);
    json_t *extradata = json_array_get(result, 1);

    if (!json_is_string(session_id) || !json_is_string(extradata)) {
        applog(LOG_ERR, "Invalid session data received from pool");
        jsonrpc_request_free(req);
        curl_easy_cleanup(curl);
        return false;
    }

    strcpy(pool->session_id, json_string_value(session_id));
    strcpy(pool->nonce, json_string_value(extradata));

    applog(LOG_NOTICE, "Stratum session successfully initiated for pool %s. Session ID: %s", pool->url, pool->session_id);
    jsonrpc_request_free(req);
    curl_easy_cleanup(curl);
    return true;
}

